{
  "name": "奥林巴斯 BX2A 显微镜机身",
  "name_en": "Olympus BX2A microscope body",
  "manufacturer": "Olympus",
  "description": "BX2A 是奥林巴斯显微镜的机身/主体平台，用于承载显微镜的光学、照明与运动部件，并在实验中完成样品观察与成像相关的基础操作。根据可见控制项，该机身支持灯状态管理、Z 轴位置调整、运动状态查询以及软限位与原点设置，适用于常规显微观察与实验室成像流程。",
  "description_en": "The BX2A is an Olympus microscope body/stand that serves as the main platform for the optical, illumination, and motion components of a microscope. In laboratory use it supports core observation and imaging tasks. Based on the exposed controls, the body supports lamp status management, Z-axis positioning, motion-state reporting, and soft-limit and origin settings for routine microscopy workflows.",
  "actions": [
    {
      "action_name": "auto-query",
      "description": "查询设备状态或参数。",
      "description_en": "Query device status or parameters."
    },
    {
      "action_name": "auto-idn",
      "description": "读取设备标识信息。",
      "description_en": "Read the device identification information."
    },
    {
      "action_name": "auto-lamp_status",
      "description": "获取/设置照明灯状态。",
      "description_en": "Get/set the lamp status."
    },
    {
      "action_name": "auto-soft_limits",
      "description": "获取/设置软限位参数。",
      "description_en": "Get/set the soft-limit settings."
    },
    {
      "action_name": "auto-movement_status",
      "description": "获取运动状态。",
      "description_en": "Get the movement status."
    },
    {
      "action_name": "auto-move_relative",
      "description": "使机身的电动轴按相对位移移动。",
      "description_en": "Move the motorized axis by a relative displacement."
    },
    {
      "action_name": "auto-z",
      "description": "获取/设置 Z 轴位置。",
      "description_en": "Get/set the Z-axis position."
    },
    {
      "action_name": "auto-init_origin",
      "description": "定义原点位置。",
      "description_en": "Define the origin position."
    }
  ],
  "tag_hints": [
    "optical microscopy",
    "microscope body",
    "Olympus BX2A",
    "motorized focus",
    "Z-axis positioning",
    "illumination control",
    "soft limits"
  ]
}

